<?php namespace App\Services; use App\Contracts\SmsProvider; use Illuminate\Support\Facades\Log; use RuntimeException; class LogSmsProvider implements SmsProvider {public function send(string $to,string $message,string $dedupeKey):void {if(config('services.sms.fail')) throw new RuntimeException('محاكاة تعطل مزود SMS'); Log::info('SMS simulated',['to'=>$to,'message'=>$message,'key'=>$dedupeKey]);}}
